const RangedStackedBarChart = ({
  isAnimationActive = true,
  defaultIndex,
}: {
  isAnimationActive?: boolean;
  defaultIndex?: TooltipIndex;
}) => (
  <BarChart
    style={{ width: '100%', maxWidth: '700px', maxHeight: '70vh', aspectRatio: 1.618 }}
    responsive
    data={rangedStackedBarData}
    id="recharts-ranged-stacked-bar-chart"
    margin={{
      top: 20,
      right: 20,
      bottom: 20,
      left: 20,
    }}
  >
    <XAxis dataKey="name" />
    <YAxis width="auto" />
    <Tooltip defaultIndex={defaultIndex} />
    <BarStack radius={25}>
      <Bar
        dataKey="value1"
        {...lightTheme.graphicalItems[0]}
        maxBarSize={50}
        isAnimationActive={isAnimationActive}
        activeBar={{ fillOpacity: 1 }}
      />
      <Bar
        dataKey="value2"
        {...lightTheme.graphicalItems[1]}
        maxBarSize={50}
        isAnimationActive={isAnimationActive}
        activeBar={{ fillOpacity: 1 }}
      />
      <Bar
        dataKey="value3"
        {...lightTheme.graphicalItems[2]}
        maxBarSize={50}
        isAnimationActive={isAnimationActive}
        activeBar={{ fillOpacity: 1 }}
      />
    </BarStack>
    <RechartsDevtools />
  </BarChart>
);

export default RangedStackedBarChart;
